GK_FLASHCARDS = [
 ('3.3', 'What is the 3-2-1 backup rule, and what does ransomware add to it?',
  'Keep three copies of data, on two kinds of media, with one off-site. Against ransomware, at least one copy must also be offline or immutable, because attackers deliberately find and encrypt or delete reachable backups before they detonate.'),
 ('3.3', 'Why is replication not a backup?',
  'Replication (for example locally or geo-redundant cloud storage) copies every change to another location almost immediately, including deletions and ransomware encryption. It protects against losing a site, not against bad data. Backups keep point-in-time versions you can go back to.'),
 ('3.3', 'Why must backups be restore-tested?',
  'A backup is only proven when it has been restored. Corrupt media, missing system state, forgotten encryption keys and restores slower than the recovery time objective are all discovered by testing, or else during the incident.'),
 ('3.2', 'After a domain compromise, why reset the krbtgt account password twice?',
  'krbtgt signs every Kerberos ticket, and an attacker who stole its hash can forge "golden tickets". Active Directory keeps the current and previous password, so one reset still leaves forged tickets valid. Two resets, spaced to allow replication, invalidate them.'),
 ('3.2', 'What is the difference between an event, an alert and an incident?',
  'An event is any observable occurrence. An alert is an event a tool flagged as worth review. An incident is a confirmed violation, or imminent threat of violation, of security policy. Most alerts never become incidents, which is why triage exists.'),
]

GK_QUIZ = [
 ('3.3', 'Ransomware encrypted a file share, and its geo-redundant replica is also encrypted. Why?',
  ['The replica was misconfigured', 'Replication copies changes, including the encryption, to the second region', 'Geo-redundant storage cannot be encrypted', 'The attacker had separate access to the second region'],
  1, 'Replication is designed to mirror changes quickly, and it cannot tell malicious changes from legitimate ones. Recovery needs point-in-time backups, ideally immutable or offline.'),
 ('3.2', 'An attacker stole the krbtgt hash. Why is resetting its password once not enough?',
  ['The reset takes 24 hours to apply', 'Domain controllers still accept tickets signed with the previous password', 'krbtgt cannot be reset', 'Golden tickets do not depend on krbtgt'],
  1, 'Active Directory keeps the current and previous krbtgt keys so tickets survive a normal change. A second reset retires the stolen key.'),
]

